def g(n):
    return n**2 - n + 1

# Test parity for small values
for k in range(10):
    for x in range(k + 1):
        y = k - x
        # Proposed structure: f(x, y) = g(k) + x
        f_xy = g(k) + x
        is_odd = f_xy % 2 != 0
        print(f"f({x}, {y}) = {f_xy}, Odd: {is_odd}")

# Test the derived parity relationship: f(x, y) is odd iff x is even
def check_parity(x, y):
    k = x + y
    f_xy = g(k) + x
    return (f_xy % 2 != 0) == (x % 2 == 0)

print("\nChecking relationship:")
for x in range(10):
    for y in range(10):
        if not check_parity(x, y):
            print(f"Mismatch at ({x}, {y})")

# Calculate N for 0 <= x, y < 10
N_check = 0
for x in range(10):
    for y in range(10):
        if x % 2 == 0:
            N_check += 1
print(f"\nN calculated based on x being even: {N_check}")

def f1(x, y):
    s = x + y
    triangular_s = s * (s + 1) // 2
    return triangular_s + x

count = 0
limit = 5
for x in range(limit):
    for y in range(limit):
        if f1(x, y) % 2 != 0:
            count += 1
print(count)

